steps.command:
python3 - <<'E'
p='tests/unit/providers/alma/test_alma.py'
s=open(p).read()
s=s.replace("mock_git_clone, helpers):","mock_git_clone, helpers, auto_fake_fixdate_finder):")
s=s.replace("def test_modularity_parsing(helpers):","def test_modularity_parsing(helpers, auto_fake_fixdate_finder):")
s=s.replace("Parser(ws=workspace, logger=None)","Parser(ws=workspace, logger=None, fixdater=auto_fake_fixdate_finder)")
s=s.replace("Parser(ws=workspace)","Parser(ws=workspace, fixdater=auto_fake_fixdate_finder)")
s+='''

def test_fix_dates_and_library_clones(helpers, fake_fixdate_finder):
    workspace = helpers.provider_workspace_helper(name=Provider.name())
    parser = Parser(ws=workspace, fixdater=fake_fixdate_finder(responses=[]))
    entry = {
        "id": "ALSA-2019:3706",
        "published": "2019-11-05T23:30:00-02:00",
        "affected": [
            {
                "package": {"ecosystem": "AlmaLinux:8", "name": "lua"},
                "ranges": [{"type": "ECOSYSTEM", "events": [{"introduced": "0"}, {"fixed": "5.3.4-11.el8"}]}],
            }
        ],
    }
    _, _, record = parser._normalize(entry, "8")
    assert len(record["affected"]) == 2
    assert record["affected"][1]["package"]["name"] == "lua-libs"
    for affected in record["affected"]:
        assert affected["ranges"][0]["database_specific"]["anchore"]["fixes"] == [
            {"version": "5.3.4-11.el8", "date": "2019-11-06", "kind": "advisory"}
        ]
    assert record["database_specific"]["anchore"] == {"record_type": "advisory"}
'''
open(p,'w').write(s)
E
PYTHONPATH=src .venv/bin/python -m pytest -q tests/unit 2>&1 | tail -6
